// apb_gpio: APB4 GPIO peripheral with interrupts.
// Implements interface_spec.md per microarchitecture.md (zero wait states,
// no state machine, 32-bit registers masked to N pins).
module apb_gpio #(
    parameter integer ADDR_WIDTH = 8,
    parameter integer N          = 8
) (
    input  wire                  pclk,
    input  wire                  presetn,
    input  wire [ADDR_WIDTH-1:0] paddr,
    input  wire                  psel,
    input  wire                  penable,
    input  wire                  pwrite,
    input  wire [31:0]           pwdata,
    input  wire [3:0]            pstrb,
    output wire [31:0]           prdata,
    output wire                  pready,
    output wire                  pslverr,
    input  wire [N-1:0]          gpio_in,
    output wire [N-1:0]          gpio_out,
    output wire [N-1:0]          gpio_oe,
    output wire                  irq
);

    // Bits 0 .. N-1 set: the pins that exist.
    localparam [31:0] PINS = {32{1'b1}} >> (32 - N);

    localparam [3:0] IDX_DATA_OUT    = 4'd0;
    localparam [3:0] IDX_DIR         = 4'd1;
    localparam [3:0] IDX_DATA_IN     = 4'd2;
    localparam [3:0] IDX_INTR_RISE   = 4'd3;
    localparam [3:0] IDX_INTR_FALL   = 4'd4;
    localparam [3:0] IDX_INTR_HIGH   = 4'd5;
    localparam [3:0] IDX_INTR_LOW    = 4'd6;
    localparam [3:0] IDX_INTR_ENABLE = 4'd7;
    localparam [3:0] IDX_INTR_STATUS = 4'd8;

    // Registers (32 bits wide at every N; bits N and up stay zero).
    reg [31:0] data_out;
    reg [31:0] dir;
    reg [31:0] in_q;
    reg [31:0] in_prev;
    reg [31:0] intr_rise;
    reg [31:0] intr_fall;
    reg [31:0] intr_high;
    reg [31:0] intr_low;
    reg [31:0] intr_enable;
    reg [31:0] intr_status;

    // APB decode.
    wire       access = psel && penable;
    wire [3:0] index  = paddr[5:2];
    wire       mapped = (paddr[1:0] == 2'b00)
                     && ((paddr >> 6) == {ADDR_WIDTH{1'b0}})
                     && (index <= IDX_INTR_STATUS);
    wire       wr     = access && pwrite && mapped;
    wire       rd     = access && !pwrite && mapped;

    // Write mask: byte strobes expanded to 32 bits, limited to existing pins.
    wire [31:0] strb_mask = {{8{pstrb[3]}}, {8{pstrb[2]}},
                             {8{pstrb[1]}}, {8{pstrb[0]}}};
    wire [31:0] wmask     = strb_mask & PINS;
    wire [31:0] wmerge_out  = (data_out    & ~wmask) | (pwdata & wmask);
    wire [31:0] wmerge_dir  = (dir         & ~wmask) | (pwdata & wmask);
    wire [31:0] wmerge_rise = (intr_rise   & ~wmask) | (pwdata & wmask);
    wire [31:0] wmerge_fall = (intr_fall   & ~wmask) | (pwdata & wmask);
    wire [31:0] wmerge_high = (intr_high   & ~wmask) | (pwdata & wmask);
    wire [31:0] wmerge_low  = (intr_low    & ~wmask) | (pwdata & wmask);
    wire [31:0] wmerge_en   = (intr_enable & ~wmask) | (pwdata & wmask);

    // Input widened to 32 bits with zeros above N.
    reg [31:0] gpio_in_w;
    always @(*) begin
        gpio_in_w          = 32'd0;
        gpio_in_w[N-1:0]   = gpio_in;
    end

    // Detection (combinational from the two samples and enables before the edge).
    wire [31:0] rise     = in_q & ~in_prev;
    wire [31:0] fall     = ~in_q & in_prev;
    wire [31:0] detected = ((rise & intr_rise) | (fall & intr_fall)
                          | (in_q & intr_high) | (~in_q & intr_low)) & PINS;
    wire        wr_status = wr && (index == IDX_INTR_STATUS);
    wire [31:0] clear     = wr_status ? (pwdata & wmask) : 32'd0;

    always @(posedge pclk) begin
        if (!presetn) begin
            data_out    <= 32'd0;
            dir         <= 32'd0;
            in_q        <= 32'd0;
            in_prev     <= 32'd0;
            intr_rise   <= 32'd0;
            intr_fall   <= 32'd0;
            intr_high   <= 32'd0;
            intr_low    <= 32'd0;
            intr_enable <= 32'd0;
            intr_status <= 32'd0;
        end else begin
            in_q    <= gpio_in_w;
            in_prev <= in_q;
            if (wr && (index == IDX_DATA_OUT))    data_out    <= wmerge_out;
            if (wr && (index == IDX_DIR))         dir         <= wmerge_dir;
            if (wr && (index == IDX_INTR_RISE))   intr_rise   <= wmerge_rise;
            if (wr && (index == IDX_INTR_FALL))   intr_fall   <= wmerge_fall;
            if (wr && (index == IDX_INTR_HIGH))   intr_high   <= wmerge_high;
            if (wr && (index == IDX_INTR_LOW))    intr_low    <= wmerge_low;
            if (wr && (index == IDX_INTR_ENABLE)) intr_enable <= wmerge_en;
            // Detection is ORed last: a detection beats a clear.
            intr_status <= (intr_status & ~clear) | detected;
        end
    end

    // Read multiplexer.
    reg [31:0] rdata;
    always @(*) begin
        case (index)
            IDX_DATA_OUT:    rdata = data_out;
            IDX_DIR:         rdata = dir;
            IDX_DATA_IN:     rdata = in_q;
            IDX_INTR_RISE:   rdata = intr_rise;
            IDX_INTR_FALL:   rdata = intr_fall;
            IDX_INTR_HIGH:   rdata = intr_high;
            IDX_INTR_LOW:    rdata = intr_low;
            IDX_INTR_ENABLE: rdata = intr_enable;
            IDX_INTR_STATUS: rdata = intr_status;
            default:         rdata = 32'd0;
        endcase
    end

    assign pready   = 1'b1;
    assign pslverr  = access && (!mapped || (pwrite && (index == IDX_DATA_IN)));
    assign prdata   = rd ? rdata : 32'd0;
    assign gpio_out = data_out[N-1:0];
    assign gpio_oe  = dir[N-1:0];
    assign irq      = |(intr_status & intr_enable);

`ifdef FORMAL
    // Design-intent assertions (not exercised by this task's checks).
    reg f_past_valid = 1'b0;
    always @(posedge pclk) f_past_valid <= 1'b1;

    always @(*) begin
        assert (pready == 1'b1);
        if (!access) begin
            assert (prdata == 32'd0);
            assert (pslverr == 1'b0);
        end
        assert (irq == |(intr_status & intr_enable));
    end

    always @(posedge pclk) begin
        if (f_past_valid && !$past(presetn)) begin
            assert (data_out == 32'd0);
            assert (dir == 32'd0);
            assert (in_q == 32'd0);
            assert (in_prev == 32'd0);
            assert (intr_status == 32'd0);
            assert (intr_enable == 32'd0);
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
