`timescale 1ns/1ps
`default_nettype none

// Self-checking testbench for apb_gpio, lanes at N = 8 and N = 32 on one APB bus.
module apb_gpio_tb;

    localparam [7:0] A_OUT  = 8'h00;
    localparam [7:0] A_DIR  = 8'h04;
    localparam [7:0] A_IN   = 8'h08;
    localparam [7:0] A_RISE = 8'h0C;
    localparam [7:0] A_FALL = 8'h10;
    localparam [7:0] A_HIGH = 8'h14;
    localparam [7:0] A_LOW  = 8'h18;
    localparam [7:0] A_EN   = 8'h1C;
    localparam [7:0] A_STAT = 8'h20;

    reg         pclk;
    reg         presetn;
    reg  [7:0]  paddr;
    reg         psel;
    reg         penable;
    reg         pwrite;
    reg  [31:0] pwdata;
    reg  [3:0]  pstrb;
    reg  [7:0]  gpio_in8;
    reg  [31:0] gpio_in32;

    wire [31:0] prdata8, prdata32;
    wire        pready8, pready32;
    wire        pslverr8, pslverr32;
    wire [7:0]  gpio_out8, gpio_oe8;
    wire [31:0] gpio_out32, gpio_oe32;
    wire        irq8, irq32;

    apb_gpio #(.ADDR_WIDTH(8), .N(8)) dut8 (
        .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel),
        .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
        .prdata(prdata8), .pready(pready8), .pslverr(pslverr8),
        .gpio_in(gpio_in8), .gpio_out(gpio_out8), .gpio_oe(gpio_oe8), .irq(irq8)
    );

    apb_gpio #(.ADDR_WIDTH(8), .N(32)) dut32 (
        .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel),
        .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
        .prdata(prdata32), .pready(pready32), .pslverr(pslverr32),
        .gpio_in(gpio_in32), .gpio_out(gpio_out32), .gpio_oe(gpio_oe32), .irq(irq32)
    );

    integer passed;
    integer failed;
    integer i;
    reg [31:0] rd8, rd32;
    reg        err8, err32;
    reg [7:0]  last_addr;
    reg [7:0]  a;
    reg [8*64-1:0] nonce;

    initial pclk = 1'b0;
    always #5 pclk = ~pclk;

    // ---------------------------------------------------------------- checks
    task check(input [8*40-1:0] what, input [31:0] got, input [31:0] exp);
        begin
            if (got === exp) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("%0s (last addr 0x%h): got 0x%h, expected 0x%h",
                       what, last_addr, got, exp);
            end
        end
    endtask

    task check_irq(input e8, input e32);
        begin
            check("irq N=8", {31'd0, irq8}, {31'd0, e8});
            check("irq N=32", {31'd0, irq32}, {31'd0, e32});
        end
    endtask

    // ---------------------------------------------------------------- timing
    task tick(input integer n);
        begin
            repeat (n) @(negedge pclk);
        end
    endtask

    task set_pins(input [7:0] v);
        begin
            @(negedge pclk);
            gpio_in8  = v;
            gpio_in32 = {24'h0, v};
        end
    endtask

    // ---------------------------------------------------------------- APB
    task xfer(input w, input [7:0] addr, input [31:0] d, input [3:0] s,
              input set_pin, input [7:0] pin8);
        begin
            @(negedge pclk);
            last_addr = addr;
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = w;
            paddr   = addr;
            pwdata  = d;
            pstrb   = w ? s : 4'b0000;
            if (set_pin) begin
                gpio_in8  = pin8;
                gpio_in32 = {24'h0, pin8};
            end
            #1;
            check("setup prdata N=8 zero", prdata8, 32'h0);
            check("setup prdata N=32 zero", prdata32, 32'h0);
            check("setup pslverr N=8 low", {31'd0, pslverr8}, 32'h0);
            check("setup pslverr N=32 low", {31'd0, pslverr32}, 32'h0);
            @(negedge pclk);
            penable = 1'b1;
            #1;
            check("access pready N=8", {31'd0, pready8}, 32'h1);
            check("access pready N=32", {31'd0, pready32}, 32'h1);
            rd8   = prdata8;
            rd32  = prdata32;
            err8  = pslverr8;
            err32 = pslverr32;
            @(negedge pclk);
            psel    = 1'b0;
            penable = 1'b0;
            pwrite  = 1'b0;
            pstrb   = 4'b0000;
            #1;
            check("idle prdata N=8 zero", prdata8, 32'h0);
            check("idle prdata N=32 zero", prdata32, 32'h0);
        end
    endtask

    task apb_write(input [7:0] addr, input [31:0] d, input [3:0] s, input exp_err);
        begin
            xfer(1'b1, addr, d, s, 1'b0, 8'h00);
            check("write pslverr N=8", {31'd0, err8}, {31'd0, exp_err});
            check("write pslverr N=32", {31'd0, err32}, {31'd0, exp_err});
        end
    endtask

    task apb_write_pin(input [7:0] addr, input [31:0] d, input [3:0] s, input [7:0] pin8);
        begin
            xfer(1'b1, addr, d, s, 1'b1, pin8);
            check("write pslverr N=8", {31'd0, err8}, 32'h0);
            check("write pslverr N=32", {31'd0, err32}, 32'h0);
        end
    endtask

    task apb_read(input [7:0] addr, input exp_err);
        begin
            xfer(1'b0, addr, 32'h0, 4'b0000, 1'b0, 8'h00);
            check("read pslverr N=8", {31'd0, err8}, {31'd0, exp_err});
            check("read pslverr N=32", {31'd0, err32}, {31'd0, exp_err});
        end
    endtask

    task read_check(input [7:0] addr, input [31:0] e32, input [31:0] e8);
        begin
            apb_read(addr, 1'b0);
            check("read data N=32", rd32, e32);
            check("read data N=8", rd8, e8);
        end
    endtask

    task read_unmapped(input [7:0] addr);
        begin
            apb_read(addr, 1'b1);
            check("unmapped read N=32 zero", rd32, 32'h0);
            check("unmapped read N=8 zero", rd8, 32'h0);
        end
    endtask

    task port_check(input [7:0] addr, input [31:0] e32);
        begin
            if (addr == A_OUT) begin
                check("gpio_out N=32", gpio_out32, e32);
                check("gpio_out N=8", {24'h0, gpio_out8}, {24'h0, e32[7:0]});
            end
            if (addr == A_DIR) begin
                check("gpio_oe N=32", gpio_oe32, e32);
                check("gpio_oe N=8", {24'h0, gpio_oe8}, {24'h0, e32[7:0]});
            end
        end
    endtask

    task check_all_zero;
        begin
            read_check(A_OUT,  32'h0, 32'h0);
            read_check(A_DIR,  32'h0, 32'h0);
            read_check(A_IN,   32'h0, 32'h0);
            read_check(A_RISE, 32'h0, 32'h0);
            read_check(A_FALL, 32'h0, 32'h0);
            read_check(A_HIGH, 32'h0, 32'h0);
            read_check(A_LOW,  32'h0, 32'h0);
            read_check(A_EN,   32'h0, 32'h0);
            read_check(A_STAT, 32'h0, 32'h0);
        end
    endtask

    task check_ports_zero;
        begin
            check("gpio_out N=8 zero", {24'h0, gpio_out8}, 32'h0);
            check("gpio_out N=32 zero", gpio_out32, 32'h0);
            check("gpio_oe N=8 zero", {24'h0, gpio_oe8}, 32'h0);
            check("gpio_oe N=32 zero", gpio_oe32, 32'h0);
            check_irq(1'b0, 1'b0);
        end
    endtask

    function [7:0] rw_addr(input integer k);
        begin
            case (k)
                0: rw_addr = A_OUT;
                1: rw_addr = A_DIR;
                2: rw_addr = A_RISE;
                3: rw_addr = A_FALL;
                4: rw_addr = A_HIGH;
                5: rw_addr = A_LOW;
                6: rw_addr = A_EN;
                default: rw_addr = A_OUT;
            endcase
        end
    endfunction

    function [7:0] un_addr(input integer k);
        begin
            case (k)
                0: un_addr = 8'h01;
                1: un_addr = 8'h02;
                2: un_addr = 8'h03;
                3: un_addr = 8'h22;
                4: un_addr = 8'h24;
                5: un_addr = 8'h28;
                6: un_addr = 8'h3C;
                7: un_addr = 8'h40;
                8: un_addr = 8'h80;
                default: un_addr = 8'hFC;
            endcase
        end
    endfunction

    // ---------------------------------------------------------------- main
    initial begin
        passed    = 0;
        failed    = 0;
        presetn   = 1'b0;
        psel      = 1'b0;
        penable   = 1'b0;
        pwrite    = 1'b0;
        paddr     = 8'h00;
        pwdata    = 32'h0;
        pstrb     = 4'b0000;
        gpio_in8  = 8'h00;
        gpio_in32 = 32'h0;
        last_addr = 8'h00;
        rd8 = 32'h0; rd32 = 32'h0; err8 = 1'b0; err32 = 1'b0;

        // 1. Reset values.
        tick(3);
        check_ports_zero;
        presetn = 1'b1;
        check_all_zero;
        check_ports_zero;

        // 2. Every read/write register: full, partial and empty strobes, bits above N.
        for (i = 0; i < 7; i = i + 1) begin
            a = rw_addr(i);
            apb_write(a, 32'hFFFFFFFF, 4'b1111, 1'b0);
            read_check(a, 32'hFFFFFFFF, 32'h000000FF);
            port_check(a, 32'hFFFFFFFF);
            apb_write(a, 32'h12345678, 4'b0101, 1'b0);
            read_check(a, 32'hFF34FF78, 32'h00000078);
            port_check(a, 32'hFF34FF78);
            apb_write(a, 32'h00000000, 4'b1000, 1'b0);
            read_check(a, 32'h0034FF78, 32'h00000078);
            port_check(a, 32'h0034FF78);
            apb_write(a, 32'hABCDEF01, 4'b0010, 1'b0);
            read_check(a, 32'h0034EF78, 32'h00000078);
            port_check(a, 32'h0034EF78);
            apb_write(a, 32'h00000000, 4'b0001, 1'b0);
            read_check(a, 32'h0034EF00, 32'h00000000);
            port_check(a, 32'h0034EF00);
            apb_write(a, 32'hFFFFFFFF, 4'b0000, 1'b0);
            read_check(a, 32'h0034EF00, 32'h00000000);
            port_check(a, 32'h0034EF00);
        end
        // Clean up: all read/write registers to zero, then clear the status.
        for (i = 0; i < 7; i = i + 1) begin
            apb_write(rw_addr(i), 32'h00000000, 4'b1111, 1'b0);
        end
        apb_write(A_STAT, 32'hFFFFFFFF, 4'b1111, 1'b0);
        read_check(A_STAT, 32'h0, 32'h0);
        check_ports_zero;

        // 3. DATA_IN: sampled, read only.
        @(negedge pclk);
        gpio_in8  = 8'h5A;
        gpio_in32 = 32'hDEADBEEF;
        read_check(A_IN, 32'hDEADBEEF, 32'h0000005A);
        apb_write(A_IN, 32'h00000000, 4'b1111, 1'b1);
        read_check(A_IN, 32'hDEADBEEF, 32'h0000005A);
        apb_write(A_IN, 32'hFFFFFFFF, 4'b1111, 1'b1);
        read_check(A_IN, 32'hDEADBEEF, 32'h0000005A);
        set_pins(8'h00);
        tick(2);
        read_check(A_IN, 32'h0, 32'h0);
        read_check(A_STAT, 32'h0, 32'h0);

        // 4. PSLVERR policy: unaligned and unmapped addresses.
        apb_write(A_OUT, 32'hFFFFFFFF, 4'b1111, 1'b0);
        for (i = 0; i < 10; i = i + 1) begin
            read_unmapped(un_addr(i));
        end
        for (i = 0; i < 10; i = i + 1) begin
            apb_write(un_addr(i), 32'h00000000, 4'b1111, 1'b1);
        end
        read_check(A_OUT, 32'hFFFFFFFF, 32'h000000FF);
        port_check(A_OUT, 32'hFFFFFFFF);
        read_check(A_STAT, 32'h0, 32'h0);
        apb_write(A_OUT, 32'h00000000, 4'b1111, 1'b0);
        port_check(A_OUT, 32'h00000000);

        // 5a. Rising edge: two-edge latency, fires once.
        apb_write(A_RISE, 32'h00000001, 4'b1111, 1'b0);
        apb_write(A_EN,   32'h00000001, 4'b1111, 1'b0);
        read_check(A_STAT, 32'h0, 32'h0);
        check_irq(1'b0, 1'b0);
        set_pins(8'h01);
        tick(1);
        check_irq(1'b0, 1'b0);
        tick(1);
        check_irq(1'b1, 1'b1);
        read_check(A_STAT, 32'h1, 32'h1);
        read_check(A_IN, 32'h1, 32'h1);
        apb_write(A_STAT, 32'h00000001, 4'b1111, 1'b0);
        tick(3);
        read_check(A_STAT, 32'h0, 32'h0);
        check_irq(1'b0, 1'b0);

        // 5b. Falling edge.
        apb_write(A_RISE, 32'h00000000, 4'b1111, 1'b0);
        apb_write(A_FALL, 32'h00000001, 4'b1111, 1'b0);
        tick(2);
        read_check(A_STAT, 32'h0, 32'h0);
        set_pins(8'h00);
        tick(2);
        check_irq(1'b1, 1'b1);
        read_check(A_STAT, 32'h1, 32'h1);
        apb_write(A_STAT, 32'h00000001, 4'b1111, 1'b0);
        tick(3);
        read_check(A_STAT, 32'h0, 32'h0);
        apb_write(A_FALL, 32'h00000000, 4'b1111, 1'b0);

        // 5c. High level: sets again after a clear; interrupt mask.
        apb_write(A_HIGH, 32'h00000002, 4'b1111, 1'b0);
        tick(2);
        read_check(A_STAT, 32'h0, 32'h0);
        set_pins(8'h02);
        tick(2);
        read_check(A_STAT, 32'h2, 32'h2);
        check_irq(1'b0, 1'b0);
        apb_write(A_EN, 32'h00000003, 4'b1111, 1'b0);
        check_irq(1'b1, 1'b1);
        apb_write(A_EN, 32'h00000001, 4'b1111, 1'b0);
        check_irq(1'b0, 1'b0);
        apb_write(A_STAT, 32'h00000002, 4'b1111, 1'b0);
        read_check(A_STAT, 32'h2, 32'h2);
        apb_write(A_STAT, 32'h00000002, 4'b1111, 1'b0);
        read_check(A_STAT, 32'h2, 32'h2);
        set_pins(8'h00);
        tick(2);
        apb_write(A_STAT, 32'h00000002, 4'b1111, 1'b0);
        read_check(A_STAT, 32'h0, 32'h0);
        apb_write(A_HIGH, 32'h00000000, 4'b1111, 1'b0);

        // 5d. Low level.
        apb_write(A_LOW, 32'h00000004, 4'b1111, 1'b0);
        tick(1);
        read_check(A_STAT, 32'h4, 32'h4);
        apb_write(A_STAT, 32'h00000004, 4'b1111, 1'b0);
        read_check(A_STAT, 32'h4, 32'h4);
        set_pins(8'h04);
        tick(2);
        apb_write(A_STAT, 32'h00000004, 4'b1111, 1'b0);
        read_check(A_STAT, 32'h0, 32'h0);
        apb_write(A_LOW, 32'h00000000, 4'b1111, 1'b0);
        set_pins(8'h00);
        tick(2);
        read_check(A_STAT, 32'h0, 32'h0);

        // 5e. Write-1-to-clear of some bits only, strobe gating, enable above N.
        apb_write(A_RISE, 32'hFFFFFFFF, 4'b1111, 1'b0);
        @(negedge pclk);
        gpio_in8  = 8'hFF;
        gpio_in32 = 32'hFFFFFFFF;
        tick(2);
        read_check(A_STAT, 32'hFFFFFFFF, 32'h000000FF);
        check_irq(1'b1, 1'b1);
        apb_write(A_EN, 32'h80000000, 4'b1111, 1'b0);
        read_check(A_EN, 32'h80000000, 32'h00000000);
        check_irq(1'b0, 1'b1);
        apb_write(A_EN, 32'h00000001, 4'b1111, 1'b0);
        apb_write(A_STAT, 32'h00000005, 4'b1111, 1'b0);
        read_check(A_STAT, 32'hFFFFFFFA, 32'h000000FA);
        check_irq(1'b0, 1'b0);
        apb_write(A_STAT, 32'hFFFFFF00, 4'b0100, 1'b0);
        read_check(A_STAT, 32'hFF00FFFA, 32'h000000FA);
        apb_write(A_STAT, 32'h000000F0, 4'b1110, 1'b0);
        read_check(A_STAT, 32'hFF00FFFA, 32'h000000FA);
        apb_write(A_STAT, 32'hFFFFFFFF, 4'b0000, 1'b0);
        read_check(A_STAT, 32'hFF00FFFA, 32'h000000FA);
        apb_write(A_STAT, 32'hFFFFFFFF, 4'b1111, 1'b0);
        read_check(A_STAT, 32'h0, 32'h0);

        // 5f. A detection beats a clear on the same edge.
        set_pins(8'h00);
        tick(2);
        read_check(A_STAT, 32'h0, 32'h0);
        set_pins(8'h01);
        tick(2);
        read_check(A_STAT, 32'h1, 32'h1);
        set_pins(8'h00);
        tick(2);
        read_check(A_STAT, 32'h1, 32'h1);
        apb_write_pin(A_STAT, 32'h00000001, 4'b1111, 8'h01);
        read_check(A_STAT, 32'h1, 32'h1);
        apb_write(A_STAT, 32'h00000001, 4'b1111, 1'b0);
        read_check(A_STAT, 32'h0, 32'h0);
        apb_write(A_RISE, 32'h00000000, 4'b1111, 1'b0);
        apb_write(A_EN, 32'h00000000, 4'b1111, 1'b0);

        // 6. Reset again from a busy state.
        apb_write(A_OUT,  32'hFFFFFFFF, 4'b1111, 1'b0);
        apb_write(A_DIR,  32'hFFFFFFFF, 4'b1111, 1'b0);
        apb_write(A_HIGH, 32'hFFFFFFFF, 4'b1111, 1'b0);
        apb_write(A_EN,   32'hFFFFFFFF, 4'b1111, 1'b0);
        set_pins(8'hFF);
        tick(2);
        port_check(A_OUT, 32'hFFFFFFFF);
        port_check(A_DIR, 32'hFFFFFFFF);
        check_irq(1'b1, 1'b1);
        set_pins(8'h00);
        presetn = 1'b0;
        tick(1);
        check_ports_zero;
        tick(1);
        presetn = 1'b1;
        check_all_zero;
        check_ports_zero;

        // Verdict.
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "unset";
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

`default_nettype wire
